import java.io.*;
import java.util.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = gc();
        while (c != '-' && (c < '0' || c > '9')) {
            if (c == -1) return 0;
            c = gc();
        }
        boolean neg = false;
        if (c == '-') { neg = true; c = gc(); }
        long v = 0;
        while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
        return neg ? -v : v;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long k = nextLong();
        long[] s = new long[n];
        for (int i = 0; i < n; i++) s[i] = nextLong();
        // Big hammer saves strength-1 hits: take the up-to-k strongest bricks with strength > 1.
        // Strengths are distinct, so sorting packed (strength, index) pairs orders by strength.
        long[] cand = new long[n];
        int c = 0;
        for (int i = 0; i < n; i++) if (s[i] > 1) cand[c++] = (s[i] << 20) | i;
        Arrays.sort(cand, 0, c);
        int take = (int) Math.min(c, Math.min(k, n));
        boolean[] used = new boolean[n];
        for (int j = 0; j < take; j++) used[(int) (cand[c - 1 - j] & ((1 << 20) - 1))] = true;
        long total = 0;
        StringBuilder big = new StringBuilder(), small = new StringBuilder();
        for (int i = 0; i < n; i++) {
            StringBuilder dst = used[i] ? big : small;
            if (dst.length() > 0) dst.append(' ');
            dst.append(i + 1);
            total += used[i] ? 1 : s[i];
        }
        StringBuilder out = new StringBuilder();
        out.append(total).append('\n').append(big.length() == 0 ? "-1" : big).append('\n')
           .append(small.length() == 0 ? "-1" : small).append('\n');
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	n := int(readInt())
	k := int(readInt())
	s := make([]int64, n)
	for i := range s {
		s[i] = readInt()
	}
	// Big hammer saves strength-1 hits: take the up-to-k strongest bricks with strength > 1.
	var cand []int
	for i := 0; i < n; i++ {
		if s[i] > 1 {
			cand = append(cand, i)
		}
	}
	sort.Slice(cand, func(a, b int) bool { return s[cand[a]] > s[cand[b]] })
	if len(cand) > min(k, n) {
		cand = cand[:min(k, n)]
	}
	used := make([]bool, n)
	for _, i := range cand {
		used[i] = true
	}
	var total int64
	var big, small []byte
	for i := 0; i < n; i++ {
		if used[i] {
			if len(big) > 0 {
				big = append(big, ' ')
			}
			big = strconv.AppendInt(big, int64(i+1), 10)
			total++
		} else {
			if len(small) > 0 {
				small = append(small, ' ')
			}
			small = strconv.AppendInt(small, int64(i+1), 10)
			total += s[i]
		}
	}
	if len(big) == 0 {
		big = []byte("-1")
	}
	if len(small) == 0 {
		small = []byte("-1")
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	w.WriteString(strconv.FormatInt(total, 10) + "\n")
	w.Write(big)
	w.WriteByte('\n')
	w.Write(small)
	w.WriteByte('\n')
}
